#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    int minDeletionSize(vector<string>& A) {
        int n = A.size(), m = A[0].size(), res = 0;
        vector<bool> sorted(n - 1, false);

        for (int j = 0; j < m; ++j) {
            bool needDelete = false;
            for (int i = 0; i < n - 1; ++i) {
                if (!sorted[i] && A[i][j] > A[i + 1][j]) {
                    needDelete = true;
                    break;
                }
            }
            if (needDelete) {
                res++;
            } else {
                for (int i = 0; i < n - 1; ++i) {
                    if (A[i][j] < A[i + 1][j]) sorted[i] = true;
                }
            }
        }
        return res;
    }
};
